// Voor elke ad:
//   - ROAS < 1.5 + spend > 20 => PAUSE
//   - ROAS > 3.0 + spend < daily_cap => SCALE +20%
//   - CTR < 0.5% + impressions > 1000 => FLAG (creative refresh)
//   - CPA > max_cpa => PAUSE
//   - CPC > 2.50 => PAUSE
// Return array van {ad_id, action, reason, metrics}
const rules = items[0].json.rules;  // uit node 2
const ads = items[1].json.data;      // uit node 3

const decisions = ads.map(ad => {
  const roas = parseFloat(ad.purchase_roas?.[0]?.value || 0);
  const spend = parseFloat(ad.spend || 0);
  const ctr = parseFloat(ad.ctr || 0);
  const cpc = parseFloat(ad.cpc || 0);
  const impressions = parseInt(ad.impressions || 0);

  if (roas < 1.5 && spend > 20) {
    return { ad_id: ad.ad_id, action: 'pause', reason: `ROAS ${roas.toFixed(2)} < 1.5, spend €${spend}`, metrics: { roas, spend, ctr, cpc } };
  }
  if (roas > 3.0 && spend < 100) {
    return { ad_id: ad.ad_id, adset_id: ad.adset_id, action: 'scale', reason: `Winner ROAS ${roas.toFixed(2)} > 3.0`, metrics: { roas, spend, ctr, cpc } };
  }
  if (ctr < 0.5 && impressions > 1000) {
    return { ad_id: ad.ad_id, action: 'flag', reason: `CTR ${ctr}% low, needs creative refresh`, metrics: { roas, spend, ctr, cpc } };
  }
  if (cpc > 2.5) {
    return { ad_id: ad.ad_id, action: 'pause', reason: `CPC €${cpc} > €2.50`, metrics: { roas, spend, ctr, cpc } };
  }
  return { ad_id: ad.ad_id, action: 'ok', reason: 'Within thresholds', metrics: { roas, spend, ctr, cpc } };
});

return decisions.map(d => ({ json: d }));

